  1522  {
  1523      Layer &layer(xcf_image.layer);
  1524      QImage &image(xcf_image.image);
  1525      PixelCopyOperation copy = nullptr;
  1526
  1527      switch (layer.type) {
  1528      case RGB_GIMAGE:
  1529      case RGBA_GIMAGE:
  1530          copy = copyRGBToRGB;
  1531          break;
  1532      case GRAY_GIMAGE:
  1533          if (layer.opacity == OPAQUE_OPACITY) {
  1534              copy = copyGrayToGray;
  1535          } else {
  1536              copy = copyGrayToRGB;
  1537          }
  1538          break;
  1539      case GRAYA_GIMAGE:
  1540          copy = copyGrayAToRGB;
  1541          break;
  1542      case INDEXED_GIMAGE:
  1543          copy = copyIndexedToIndexed;
  1544          break;
  1545      case INDEXEDA_GIMAGE:
  1546          if (xcf_image.image.depth() <= 8) {
  1547              copy = copyIndexedAToIndexed;
  1548          } else {
  1549              copy = copyIndexedAToRGB;
  1550          }
  1551      }
  1552
  1553      if (!copy) {
  1554          return;
  1555      }
  1556
  1557      // For each tile...
  1558
  1559      for (uint j = 0; j < layer.nrows; j++) {
  1560          uint y = j * TILE_HEIGHT;
  1561
  1562          for (uint i = 0; i < layer.ncols; i++) {
  1563              uint x = i * TILE_WIDTH;
  1564
  1565              // This seems the best place to apply the dissolve because it
  1566              // depends on the global position of each tile's
  1567              // pixels. Apparently it's the only mode which can apply to a
  1568              // single layer.
  1569
  1570              if (layer.mode == DISSOLVE_MODE) {
  1571                  if (!random_table_initialized) {
  1572                      initializeRandomTable();
  1573                      random_table_initialized = true;
  1574                  }
  1575                  if (layer.type == RGBA_GIMAGE) {
  1576                      dissolveRGBPixels(layer.image_tiles[j][i], x, y);
  1577                  }
  1578
  1579                  else if (layer.type == GRAYA_GIMAGE) {
  1580                      dissolveAlphaPixels(layer.alpha_tiles[j][i], x, y);
  1581                  }
  1582              }
  1583
  1584              // Shortcut for common case
  1585              if (copy == copyRGBToRGB && layer.apply_mask != 1) {
  1586                  QPainter painter(&image);
  1587                  painter.setOpacity(layer.opacity / 255.0);
  1588                  painter.setCompositionMode(QPainter::CompositionMode_Source);
  1589                  painter.drawImage(x + layer.x_offset, y + layer.y_offset, layer.image_tiles[j][i]);
  1590                  continue;
  1591              }
  1592
  1593              for (int l = 0; l < layer.image_tiles[j][i].height(); l++) {
  1594                  for (int k = 0; k < layer.image_tiles[j][i].width(); k++) {
  1595
  1596                      int m = x + k + layer.x_offset;
  1597                      int n = y + l + layer.y_offset;
  1598
  1599                      if (m < 0 || m >= image.width() || n < 0 || n >= image.height()) {
  1600                          continue;
  1601                      }
  1602
  1603                      (*copy)(layer, i, j, k, l, image, m, n);
  1604                  }
  1605              }
  1606          }
  1607      }
  1608  }
